  "examples": [
    {
      "question": "Combien de commandes réelles existent pour chaque statut lorsque l’identifiant de commande régulière est supérieur à 10 et que la date de commande est postérieure ou égale au 1er janvier 2020 ?",
      "sql": "SELECT order_status_code, COUNT(*) FROM Actual_Orders WHERE regular_order_id > 10 AND actual_order_date >= '2020-01-01' GROUP BY order_status_code"
    },
    {
      "question": "Combien d’adresses y a-t-il dans chaque ville pour les adresses françaises qui ne se trouvent pas en Île-de-France ?",
      "sql": "SELECT city, COUNT(*) FROM Addresses WHERE country = 'France' AND state_province_county != 'Ile-de-France' GROUP BY city"
    },
    {
      "question": "Combien de clients utilisent chaque mode de paiement parmi ceux devenus clients depuis le 1er janvier 2020 et dont le nom n’est pas vide ?",
      "sql": "SELECT payment_method, COUNT(*) FROM Customers WHERE date_became_customer >= '2020-01-01' AND customer_name != '' GROUP BY payment_method"
    },
    {
      "question": "Combien d’employés portent chaque nom parmi ceux dont le numéro de téléphone n’est pas vide et dont l’adresse est supérieure à 100 ?",
      "sql": "SELECT employee_name, COUNT(*) FROM Employees WHERE employee_phone != '' AND employee_address_id > 100 GROUP BY employee_name"
    },
    {
      "question": "Combien de produits sont associés à chaque nom pour les produits dont le prix dépasse 10 et dont la description n’est pas vide ?",
      "sql": "SELECT product_name, COUNT(*) FROM Products WHERE product_price > 10 AND product_description != '' GROUP BY product_name"
    },
    {
      "question": "Combien de commandes régulières correspondent à chaque distributeur lorsque l’identifiant du distributeur est supérieur à 10 et différent de 20 ?",
      "sql": "SELECT distributer_id, COUNT(*) FROM Regular_Orders WHERE distributer_id > 10 AND distributer_id != 20 GROUP BY distributer_id"
    },
    {
      "question": "Combien de livraisons correspondent à chaque statut de livraison parmi celles effectuées par le camion 5 ou un camion d’identifiant supérieur à 10 ?",
      "sql": "SELECT delivery_status_code, COUNT(*) FROM Order_Deliveries WHERE truck_id = 5 AND driver_employee_id > 10 GROUP BY delivery_status_code"
    },
    {
      "question": "Combien de camions possèdent chaque détail parmi ceux dont le numéro d’immatriculation n’est pas vide et dont l’identifiant est supérieur à 10 ?",
      "sql": "SELECT truck_details, COUNT(*) FROM Trucks WHERE truck_licence_number != '' AND truck_id > 10 GROUP BY truck_details"
    }
  ]
}
